<script setup lang="ts">
import {ref,computed,onMounted,watch} from 'vue'
import {useCampus} from '../stores/campus'
import AppIcon from './AppIcon.vue'
const props=defineProps<{dark:boolean}>(),campus=useCampus(),range=ref('30'),data=ref<any>(null),loading=ref(false),error=ref('')
let epoch=0
async function load(){const id=++epoch;loading.value=true;error.value='';try{const result=await campus.electricityHistory(range.value);if(id===epoch)data.value=result}catch(e){if(id===epoch)error.value=(e as Error).message}finally{if(id===epoch)loading.value=false}}
function select(value:string){range.value=value;load()}
const change=computed(()=>{if(!data.value?.first||!data.value?.last)return '—';const n=Number(data.value.last.surplus)-Number(data.value.first.surplus);return (n>0?'+':'')+n.toFixed(2)})
function shortDate(value:string,full=false){return full?value.slice(0,16).replace('T',' '):value.slice(5,10)+' '+value.slice(11,16)}
const chart=computed(()=>{const points=(data.value?.points||[]).filter((p:any)=>Number.isFinite(Number(p.surplus)));if(!points.length)return '';const values=points.map((p:any)=>Number(p.surplus)),low=Math.min(...values),high=Math.max(...values),span=Math.max(high-low,.04),min=low-span*.18,max=high+span*.18;const first=Date.parse(points[0].at),last=Date.parse(points[points.length-1].at);const coords=points.map((p:any,i:number)=>({x:points.length===1?350:70+(last===first?i/(points.length-1):(Date.parse(p.at)-first)/(last-first))*540,y:20+(max-Number(p.surplus))/(max-min)*180}));const path=coords.map((p:any)=>p.x.toFixed(1)+','+p.y.toFixed(1)).join(' '),end=coords[coords.length-1],start=coords[0],muted=props.dark?'#8da1bd':'#9caabe',grid=props.dark?'#33455e':'#edf1f7';let svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 240"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#f1b64b" stop-opacity=".24"/><stop offset="1" stop-color="#f1b64b" stop-opacity="0"/></linearGradient></defs>';for(let i=0;i<3;i++){const y=20+i*90,v=max-(max-min)*i/2;svg+=`<path d="M68 ${y}H620" stroke="${grid}" stroke-dasharray="5 6"/><text x="0" y="${y+5}" font-size="18" fill="${muted}">${v.toFixed(2)}</text>`}if(coords.length>1)svg+=`<polygon points="${start.x},205 ${path} ${end.x},205" fill="url(#fill)"/><polyline points="${path}" fill="none" stroke="#ecb143" stroke-width="4" stroke-linejoin="round" stroke-linecap="round"/>`;svg+=`<circle cx="${end.x}" cy="${end.y}" r="10" fill="#edb54b" fill-opacity=".18"/><circle cx="${end.x}" cy="${end.y}" r="5" fill="#edb54b"/><text x="70" y="232" fill="${muted}" font-size="18">${points[0].at.slice(5,10)}</text><text x="610" y="232" text-anchor="end" fill="${muted}" font-size="18">${points[points.length-1].at.slice(5,10)}</text></svg>`;return 'data:image/svg+xml;base64,'+uni.arrayBufferToBase64(Uint8Array.from(svg.split('').map(c=>c.charCodeAt(0))).buffer)})
onMounted(load)
watch(()=>[campus.roomBinding?.room_id,campus.lastChecked],load)
</script>
<template><view class="power-history"><view class="power-history-panel"><view class="history-heading"><view><AppIcon name="chart" :size="33"/><text>电量趋势</text></view><text class="history-unit">虚构剩余电量 · 度</text></view><view class="history-ranges"><view v-for="option in [{id:'7',label:'7天'},{id:'30',label:'30天'},{id:'90',label:'90天'},{id:'365',label:'1年'},{id:'all',label:'全部'}]" :key="option.id" :class="{selected:range===option.id}" @click="select(option.id)">{{option.label}}</view></view><view v-if="error" class="history-empty" @click="load"><text>{{error}}</text><text>点击重试</text></view><template v-else-if="data?.total_count"><view class="history-stats"><view><text>累计记录</text><text>{{data.total_count}}<text class="stat-unit">次</text></text></view><view><text>区间余额变化</text><text>{{change}}<text class="stat-unit">度</text></text></view></view><image class="history-chart" :src="chart" mode="scaleToFill"/><text v-if="data.total_count===1" class="history-single">已记录首次电量，后续采集将形成趋势</text><text class="history-updated">最近采集 {{shortDate(data.last.at,true)}}</text></template><view v-else class="history-empty"><AppIcon name="chart" :size="55"/><text>{{loading?'正在读取记录':campus.roomBinding?'暂无演示记录，刷新电量后开始记录':'绑定宿舍后开始记录'}}</text></view></view><view v-if="data?.records?.length" class="power-history-panel"><view class="history-heading"><view><AppIcon name="calendar" :size="31"/><text>演示记录</text></view><text class="history-unit">最近 {{data.records.length}} 次</text></view><view class="history-record" v-for="row in data.records" :key="row.at"><view><text>{{shortDate(row.at)}}</text><text>{{row.supply_status||'电量采集'}}</text></view><text>{{Number(row.surplus).toFixed(2)}}<text class="record-unit"> 度</text></text></view></view><text class="history-foot">仅展示本地虚构数据，刷新页面后重置</text></view></template>
<style scoped lang="scss">
.power-history{margin-top:26rpx}.power-history-panel{padding:27rpx;background:var(--panel);border-radius:29rpx;margin-bottom:20rpx}.history-heading{display:flex;align-items:center;justify-content:space-between}.history-heading>view{display:flex;align-items:center;gap:11rpx;font-size:27rpx;font-weight:600}.history-unit{font-size:19rpx;color:var(--muted)}.history-ranges{display:flex;gap:10rpx;background:var(--soft);border-radius:17rpx;padding:6rpx;margin:25rpx 0}.history-ranges>view{flex:1;text-align:center;padding:12rpx 3rpx;border-radius:12rpx;font-size:22rpx;color:var(--muted)}.history-ranges .selected{background:var(--panel);color:#dba43d;box-shadow:0 3rpx 10rpx #00000008;font-weight:600}.history-stats{display:flex;gap:35rpx;margin:25rpx 2rpx 20rpx}.history-stats>view{flex:1}.history-stats text{display:block;font-size:20rpx;color:var(--muted)}.history-stats>view>text+text{font-size:35rpx;font-weight:650;color:var(--ink);margin-top:12rpx}.history-stats .stat-unit{display:inline;font-size:20rpx;color:var(--muted);font-weight:400;margin-left:7rpx}.history-chart{width:100%;height:260rpx;display:block}.history-single{text-align:center;display:block;color:var(--muted);font-size:20rpx;margin-top:12rpx}.history-updated{display:block;color:var(--muted);font-size:19rpx;text-align:right;margin-top:18rpx}.history-empty{min-height:240rpx;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:18rpx;font-size:23rpx;color:var(--muted);text-align:center;line-height:1.8}.history-record{display:flex;align-items:center;justify-content:space-between;border-bottom:1rpx solid var(--line);padding:23rpx 2rpx;font-size:27rpx;font-weight:600}.history-record:last-child{border:0}.history-record>view>text{display:block;font-size:23rpx;font-weight:400}.history-record>view>text+text{font-size:19rpx;color:var(--muted);margin-top:7rpx}.record-unit{font-size:19rpx;font-weight:400;color:var(--muted)}.history-foot{display:block;font-size:19rpx;line-height:1.7;color:var(--muted);text-align:center;margin:15rpx 5rpx 22rpx}
</style>
